"use client"

import type React from "react"
import { useState } from "react"
import { Search, ExternalLink, AlertTriangle, Filter, X } from "lucide-react"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { contentItems as mockContentItems, type ContentItem } from "@/lib/mock-data"
import { ContentDetailModal } from "@/components/content-detail-modal"
import { PageLayout } from "@/components/page-layout"

export default function ContentReviewPage() {
  const [searchQuery, setSearchQuery] = useState("")
  const [selectedItems, setSelectedItems] = useState<string[]>(["1", "3"])
  const [contentItems, setContentItems] = useState<ContentItem[]>(mockContentItems)
  const [selectedItem, setSelectedItem] = useState<ContentItem | null>(null)
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [showFilters, setShowFilters] = useState(false)
  const [filterCategory, setFilterCategory] = useState<string>("all")
  const [filterStatus, setFilterStatus] = useState<string>("all")

  // Get unique categories
  const categories = Array.from(new Set(contentItems.map((item) => item.category)))

  const filteredItems = contentItems.filter((item) => {
    const matchesSearch =
      item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.description.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesCategory = filterCategory === "all" || item.category === filterCategory
    const matchesStatus = filterStatus === "all" || item.status === filterStatus
    return matchesSearch && matchesCategory && matchesStatus
  })

  const toggleItem = (id: string, e: React.MouseEvent) => {
    e.stopPropagation()
    setSelectedItems((prev) => (prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]))
  }

  const openItemDetail = (item: ContentItem) => {
    setSelectedItem(item)
    setIsModalOpen(true)
  }

  const handleApprove = (id: string) => {
    setContentItems((prev) => prev.map((item) => (item.id === id ? { ...item, status: "approved" as const } : item)))
    setIsModalOpen(false)
  }

  const handleReject = (id: string, reason: string) => {
    setContentItems((prev) => prev.map((item) => (item.id === id ? { ...item, status: "rejected" as const } : item)))
    setIsModalOpen(false)
  }

  const handleBatchApprove = () => {
    setContentItems((prev) =>
      prev.map((item) => (selectedItems.includes(item.id) ? { ...item, status: "approved" as const } : item)),
    )
    setSelectedItems([])
  }

  const getStatusIcon = (item: ContentItem) => {
    if (item.status === "warning") {
      return <AlertTriangle className="h-5 w-5 text-amber-500" />
    }
    return null
  }

  return (
    <PageLayout
      title="开始审核"
      headerActions={
        <Button variant="ghost" size="icon" className="text-primary-blue">
          <ExternalLink className="h-5 w-5" />
        </Button>
      }
    >
      {/* Search and Filter */}
      <div className="max-w-5xl mx-auto px-6 py-4 space-y-3">
        <div className="flex gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              placeholder="搜索标题或内容..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 bg-gray-100 border-0 rounded-xl"
            />
            {searchQuery && (
              <button className="absolute right-3 top-1/2 -translate-y-1/2" onClick={() => setSearchQuery("")}>
                <X className="h-4 w-4 text-gray-400" />
              </button>
            )}
          </div>
          <Button
            variant="outline"
            size="icon"
            className={`rounded-xl ${showFilters ? "bg-primary-blue text-white" : ""}`}
            onClick={() => setShowFilters(!showFilters)}
          >
            <Filter className="h-4 w-4" />
          </Button>
        </div>

        {/* Filter Options */}
        {showFilters && (
          <div className="bg-white p-4 rounded-xl shadow-sm space-y-3">
            <div>
              <p className="text-sm font-medium text-gray-700 mb-2">分类筛选</p>
              <div className="flex flex-wrap gap-2">
                <Button
                  variant={filterCategory === "all" ? "default" : "outline"}
                  size="sm"
                  className={`rounded-full text-xs ${filterCategory === "all" ? "bg-primary-blue" : ""}`}
                  onClick={() => setFilterCategory("all")}
                >
                  全部
                </Button>
                {categories.map((cat) => (
                  <Button
                    key={cat}
                    variant={filterCategory === cat ? "default" : "outline"}
                    size="sm"
                    className={`rounded-full text-xs ${filterCategory === cat ? "bg-primary-blue" : ""}`}
                    onClick={() => setFilterCategory(cat)}
                  >
                    {cat}
                  </Button>
                ))}
              </div>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-700 mb-2">状态筛选</p>
              <div className="flex flex-wrap gap-2">
                {[
                  { value: "all", label: "全部" },
                  { value: "pending", label: "待审核" },
                  { value: "approved", label: "已通过" },
                  { value: "rejected", label: "已拒绝" },
                  { value: "warning", label: "需关注" },
                ].map((status) => (
                  <Button
                    key={status.value}
                    variant={filterStatus === status.value ? "default" : "outline"}
                    size="sm"
                    className={`rounded-full text-xs ${filterStatus === status.value ? "bg-primary-blue" : ""}`}
                    onClick={() => setFilterStatus(status.value)}
                  >
                    {status.label}
                  </Button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Batch Actions */}
        {selectedItems.length > 0 && (
          <div className="bg-primary-blue/10 p-3 rounded-xl flex items-center justify-between">
            <span className="text-sm text-primary-blue font-medium">已选择 {selectedItems.length} 项</span>
            <div className="flex gap-2">
              <Button
                size="sm"
                variant="outline"
                className="rounded-full bg-transparent"
                onClick={() => setSelectedItems([])}
              >
                取消选择
              </Button>
              <Button size="sm" className="bg-primary-blue rounded-full" onClick={handleBatchApprove}>
                批量通过
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* Content List */}
      <div className="max-w-5xl mx-auto px-6 pb-8">
        <div className="bg-white rounded-2xl shadow-sm overflow-hidden">
          {filteredItems.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <p>没有找到匹配的内容</p>
            </div>
          ) : (
            filteredItems.map((item, index) => (
              <div
                key={item.id}
                className={`flex items-start gap-4 p-4 ${
                  index !== filteredItems.length - 1 ? "border-b border-gray-100" : ""
                } hover:bg-gray-50 transition-colors cursor-pointer`}
                onClick={() => openItemDetail(item)}
              >
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <h3 className="font-medium text-gray-900">{item.title}</h3>
                    {item.tag && (
                      <Badge variant="outline" className="text-xs border-green-500 text-green-500 rounded-full">
                        {item.tag}
                      </Badge>
                    )}
                    {item.status === "approved" && (
                      <Badge className="text-xs bg-green-100 text-green-600 rounded-full">已通过</Badge>
                    )}
                    {item.status === "rejected" && (
                      <Badge className="text-xs bg-red-100 text-red-600 rounded-full">已拒绝</Badge>
                    )}
                  </div>
                  <p className="text-sm text-gray-500 mt-1">{item.description}</p>
                  <div className="flex items-center gap-3 mt-2 text-xs text-gray-400">
                    <span>{item.category}</span>
                    <span>{item.createdAt}</span>
                  </div>
                </div>
                <div className="flex items-center" onClick={(e) => toggleItem(item.id, e)}>
                  {getStatusIcon(item) || (
                    <div
                      className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                        selectedItems.includes(item.id) ? "bg-primary-blue border-primary-blue" : "border-gray-300"
                      }`}
                    >
                      {selectedItems.includes(item.id) && (
                        <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20">
                          <path
                            fillRule="evenodd"
                            d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                            clipRule="evenodd"
                          />
                        </svg>
                      )}
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Content Detail Modal */}
      <ContentDetailModal
        item={selectedItem}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onApprove={handleApprove}
        onReject={handleReject}
      />
    </PageLayout>
  )
}
